def choose_move(observation):
    def g(key, default=None):
        try:
            return observation.get(key, default)
        except Exception:
            return default

    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def clamp_step(a, b):
        return 0 if a == b else (1 if b > a else -1)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    sx_sy = pos(g("self_position"), (0, 0))
    sx, sy = sx_sy
    ox_oy = pos(g("opponent_position"), (sx, sy))
    ox, oy = ox_oy

    env = g("environment_name", "resource_collection") or "resource_collection"
    role = g("self_role", "pursuer") or "pursuer"

    width = g("grid_width", 0) or 0
    height = g("grid_height", 0) or 0

    def best_target(items, prefer_far=False, anchor=None):
        if not items:
            return None
        best = None
        best_score = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            s = dist((sx, sy), p)
            if anchor is not None:
                s2 = dist(anchor, p)
                score = (s2, s) if prefer_far else (s, -s2)
            else:
                score = (-s if prefer_far else s,)
            if best is None or score < best_score:
                best = p
                best_score = score
        return best

    def move_toward(target):
        if target is None:
            return [0, 0]
        tx, ty = target
        return [clamp_step(sx, tx), clamp_step(sy, ty)]

    def move_away(target):
        if target is None:
            return [0, 0]
        tx, ty = target
        return [clamp_step(tx, sx), clamp_step(ty, sy)]

    if env == "pursuit_evasion":
        if role == "pursuer":
            target = pos(g("opponent_position"), None)
            if target is not None:
                return move_toward(target)
            return [0, 0]
        # evader: maximize distance from opponent, with corner bias if known
        corners = []
        if width and height:
            corners = [(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)]
        if corners:
            target = max(corners, key=lambda c: dist(c, (ox, oy)))
            mv = move_away((ox, oy))
            if mv == [0, 0]:
                mv = move_toward(target)
            return mv
        return move_away((ox, oy))

    if env == "territory_control":
        unclaimed = g("unclaimed_cells", []) or []
        opp_terr = g("opponent_territory", []) or []
        my_terr = g("self_territory", []) or []
        target = best_target(unclaimed)
        if target is None:
            target = best_target(opp_terr)
        if target is None and my_terr:
            # move toward frontier: farthest own cell from self encourages spreading
            target = best_target(my_terr, prefer_far=True)
        if target is None:
            if width and height:
                target = (width // 2, height // 2)
            else:
                target = (ox, oy)
        return move_toward(target)

    resources = g("resources", []) or []
    if not resources:
        # no resources: drift toward opponent for interaction, but avoid deadlock
        if width and height:
            center = (width // 2, height // 2)
            if dist((sx, sy), (ox, oy)) < 3:
                return move_away((ox, oy))
            return move_toward(center)
        return move_toward((ox, oy))

    target = best_target(resources)
    if target is None:
        return [0, 0]

    # If opponent is much closer to the best resource, prefer a safer alternative or spacing.
    if ox_oy != (sx, sy):
        my_d = dist((sx, sy), target)
        opp_d = dist((ox, oy), target)
        if opp_d + 1 < my_d:
            if width and height:
                safe = max([(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)], key=lambda c: dist(c, (ox, oy)))
                return move_toward(safe)
            return move_away((ox, oy))

    return move_toward(target)

